import{_ as e,o as t,c as i,ai as r}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"CI/CD 实战与面试","description":"","frontmatter":{},"headers":[],"relativePath":"guide/devops/cicd-interview.md","filePath":"guide/devops/cicd-interview.md"}'),l={name:"guide/devops/cicd-interview.md"};function d(o,a,n,h,c,s){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="ci-cd-实战与面试" tabindex="-1">CI/CD 实战与面试 <a class="header-anchor" href="#ci-cd-实战与面试" aria-label="Permalink to “CI/CD 实战与面试”">​</a></h1><p>目标：讲清流水线在干什么，并能描述一条「提交代码 → 构建测试 → 部署」的最小路径。</p><hr><h2 id="面试高频问法" tabindex="-1">面试高频问法 <a class="header-anchor" href="#面试高频问法" aria-label="Permalink to “面试高频问法”">​</a></h2><ol><li>什么是 CI？什么是 CD？你们流水线有哪些阶段？</li><li>一次提交后，你们服务器/环境怎么更新？</li><li>构建失败你怎么查？发布失败怎么回滚？</li><li>有没有做过分支策略？（main / feature / release）</li><li>密钥、环境变量怎么管理？会不会打进镜像？</li></ol><hr><h2 id="口述参考-短版" tabindex="-1">口述参考（短版） <a class="header-anchor" href="#口述参考-短版" aria-label="Permalink to “口述参考（短版）”">​</a></h2><p><strong>CI：</strong> 代码合并后自动构建 + 跑测试，尽早发现问题。</p><p><strong>CD：</strong> 把可发布产物自动推到测试/预发；生产是否全自动取决于团队，很多公司保留人工确认。</p><p><strong>一条典型流水线：</strong><br> checkout → 安装依赖/编译 → 单测 → 打包（jar/镜像）→ 部署到环境 → 健康检查。</p><p><strong>回滚：</strong> 保留上一版产物/镜像 tag；出问题切回上一版本并观察健康检查与日志。</p><hr><h2 id="实战-你要能讲清的最小落地" tabindex="-1">实战：你要能讲清的最小落地 <a class="header-anchor" href="#实战-你要能讲清的最小落地" aria-label="Permalink to “实战：你要能讲清的最小落地”">​</a></h2><p>不必背 Jenkins 全插件。抓住你真实用过的一种即可（GitHub Actions / GitLab CI / Jenkins）。</p><h3 id="流水线阶段-按这个记" tabindex="-1">流水线阶段（按这个记） <a class="header-anchor" href="#流水线阶段-按这个记" aria-label="Permalink to “流水线阶段（按这个记）”">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>做什么</th><th>失败了怎么办</th></tr></thead><tbody><tr><td>构建</td><td>编译、打 jar/镜像</td><td>看编译日志、依赖、JDK 版本</td></tr><tr><td>测试</td><td>单测/关键冒烟</td><td>先修测试或确认是否环境不稳</td></tr><tr><td>发布</td><td>拷贝产物或拉镜像启动</td><td>回滚上一版本、看启动日志</td></tr><tr><td>验证</td><td>健康检查、核心接口探活</td><td>不通过则停止放量/回滚</td></tr></tbody></table><h3 id="口述模板-套你自己的项目" tabindex="-1">口述模板（套你自己的项目） <a class="header-anchor" href="#口述模板-套你自己的项目" aria-label="Permalink to “口述模板（套你自己的项目）”">​</a></h3><blockquote><p>我们一般是提交到主开发分支后触发流水线：先构建打包，再跑基础测试，通过后部署到测试环境。生产发布会确认版本号。出问题优先看流水线日志和容器/服务启动日志，必要时回滚到上一个稳定包。</p></blockquote><h3 id="安全底线-加分" tabindex="-1">安全底线（加分） <a class="header-anchor" href="#安全底线-加分" aria-label="Permalink to “安全底线（加分）”">​</a></h3><ul><li>密码、Token 走环境变量/密钥管理，不写死在仓库</li><li>不同环境（dev/test/prod）配置分离</li><li>镜像打 tag（别只会 <code>latest</code>）</li></ul><hr><h2 id="结合你简历怎么讲" tabindex="-1">结合你简历怎么讲 <a class="header-anchor" href="#结合你简历怎么讲" aria-label="Permalink to “结合你简历怎么讲”">​</a></h2><p>若有 Docker + CI/CD（如 MES）：</p><blockquote><p>依赖服务容器化，业务包通过流水线构建；发布后看服务是否起来、关键接口是否通。发布异常会停更并回滚。</p></blockquote><p>没完整流水线也如实说：</p><blockquote><p>目前更多是手动/半自动发布，但我清楚标准流水线该有构建、测试、部署、回滚，正在往自动化补齐。</p></blockquote><p>比硬编一整套 Jenkins 更稳。</p><hr><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to “常见坑”">​</a></h2><ul><li>「流水线绿了但服务没起来」——缺健康检查</li><li>本地能过、CI 失败——JDK/Node 版本不一致</li><li>配置打进镜像——换环境要重新构建，还容易泄密</li></ul><hr><h2 id="自测清单" tabindex="-1">自测清单 <a class="header-anchor" href="#自测清单" aria-label="Permalink to “自测清单”">​</a></h2><ul><li>[ ] 能画/能说 5 个阶段：取代码→构建→测试→部署→验证</li><li>[ ] 能说一次构建失败或发布回滚经历（真实即可）</li><li>[ ] 知道密钥不该进 Git</li><li>[ ] 能区分 CI 和 CD 各解决什么问题</li></ul>',33)])])}const k=e(l,[["render",d]]);export{b as __pageData,k as default};
